392: /**
393:  * Dynamically queries GitHub Search API to aggregate real repository counts and star metrics per language
394:  */
395: export const getLiveLanguageRankings = async (timeframe = 'today') => {
396:   const cacheKey = `${LANG_CACHE_PREFIX}${timeframe}`;
397:   try {
398:     const cached = localStorage.getItem(cacheKey);
399:     if (cached) {
400:       const { data, ts } = JSON.parse(cached);
401:       if (Date.now() - ts < LANG_CACHE_TTL && Array.isArray(data) && data.length > 0) {
402:         return { data, isLive: true, fromCache: true, lastUpdated: new Date(ts).toISOString() };
403:       }
404:     }
405:   } catch {
406:     // ignore parse error
407:   }
408: 
409:   // Calculate timeframe date query
410:   const date = new Date();
411:   if (timeframe === 'today') date.setDate(date.getDate() - 1);
412:   else if (timeframe === '7d') date.setDate(date.getDate() - 7);
413:   else if (timeframe === '30d') date.setDate(date.getDate() - 30);
414:   else if (timeframe === '365d') date.setFullYear(date.getFullYear() - 1);
415: 
416:   const dateStr = date.toISOString().split('T')[0];
417: 
418:   try {
419:     // Fetch top high-velocity repositories created or pushed in this timeframe
420:     const response = await fetchWithRetry(
421:       `${GITHUB_API_BASE}/search/repositories?q=created:>${dateStr}+stars:>50&sort=stars&order=desc&per_page=100`
422:     );
423:     const result = await response.json();
424:     const items = result.items || [];
425: 
426:     // Aggregate by language
427:     const langStats = {};
428:     for (const repo of items) {
429:       const lang = repo.language;
430:       if (!lang) continue;
431:       if (!langStats[lang]) {
432:         langStats[lang] = {
433:           totalStars: 0,
434:           repoCount: 0,
435:           topRepos: [],
436:         };
437:       }
438:       langStats[lang].totalStars += repo.stargazers_count || 0;
439:       langStats[lang].repoCount += 1;
440:       if (langStats[lang].topRepos.length < 3) {
441:         langStats[lang].topRepos.push({
442:           fullName: repo.full_name,
443:           name: repo.name,
444:           stars: repo.stargazers_count >= 1000 ? `${(repo.stargazers_count / 1000).toFixed(1)}k` : `${repo.stargazers_count}`,
445:           desc: repo.description || 'No description provided.',
446:           link: `/dashboard?query=${encodeURIComponent(repo.full_name)}`,
447:         });
448:       }
449:     }
450: 
451:     const payload = {
452:       langStats,
453:       totalIndexed: items.length,
454:       timestamp: Date.now(),
455:     };
456: 
457:     try {
458:       localStorage.setItem(cacheKey, JSON.stringify({ data: payload, ts: Date.now() }));
459:     } catch {
460:       // localStorage quota
461:     }
462: 
463:     return { data: payload, isLive: true, fromCache: false, lastUpdated: new Date().toISOString() };
464:   } catch (err) {
465:     // If rate limited or offline, return fallback
466:     return { data: null, isLive: false, error: err.message };
467:   }
468: };
