584: /**
585:  * Recommend similar repositories using explainable signals (shared language, overlapping topics).
586:  * Never invents an opaque or synthetic similarity score.
587:  */
588: export const getRepositoryAlternatives = async (repo) => {
589:   if (!repo) return { items: [], fetchedAt: new Date().toISOString() };
590: 
591:   const targetLang = repo.language || '';
592:   const targetTopics = Array.isArray(repo.topics) ? repo.topics : [];
593:   const fullName = repo.full_name || repo.name || '';
594: 
595:   // Formulate a targeted search query
596:   let queryTerms = [];
597:   if (targetLang) queryTerms.push(`language:${targetLang}`);
598:   if (targetTopics.length > 0) {
599:     queryTerms.push(targetTopics.slice(0, 2).map((t) => `topic:${t}`).join(' '));
600:   } else {
601:     queryTerms.push('stars:>500');
602:   }
603: 
604:   const query = `${queryTerms.join(' ')} stars:>100`;
605: 
606:   try {
607:     const res = await searchRepositories({ query, sort: 'stars', order: 'desc', perPage: 8 });
608:     const candidates = (res.items || []).filter((item) => (item.full_name || item.name) !== fullName);
609: 
610:     const mapped = candidates.slice(0, 4).map((item) => {
611:       const itemTopics = Array.isArray(item.topics) ? item.topics : [];
612:       const sharedTopics = itemTopics.filter((t) => targetTopics.includes(t));
613:       const sharedLanguage = item.language && item.language === targetLang ? item.language : null;
614: 
615:       const reasons = [];
616:       if (sharedLanguage) reasons.push(`primary language ${sharedLanguage}`);
617:       if (sharedTopics.length > 0) reasons.push(`shared ${sharedTopics.length === 1 ? 'topic' : 'topics'} #${sharedTopics.join(', #')}`);
618:       if (reasons.length === 0) reasons.push('similar open-source development ecosystem');
619: 
620:       return {
621:         ...item,
622:         matchReason: `Matched because both projects share ${reasons.join(' and ')}.`,
623:         sharedTopics,
624:         sharedLanguage,
625:       };
626:     });
627: 
628:     return {
629:       items: mapped,
630:       fetchedAt: new Date().toISOString(),
631:     };
632:   } catch (err) {
633:     return { items: [], error: err.message, fetchedAt: new Date().toISOString() };
634:   }
635: };
