637: /**
638:  * What Changed? Digest
639:  * Summarizes verifiable recent releases, merged pull requests, and commits.
640:  * Never invents activity or summaries.
641:  */
642: export const getWhatChangedDigest = async (owner, repo, days = 30) => {
643:   const sinceDate = new Date(Date.now() - days * 24 * 60 * 60 * 1000).toISOString();
644:   const sinceDateOnly = sinceDate.split('T')[0];
645: 
646:   const [commitsRes, releasesRes, prsRes] = await Promise.allSettled([
647:     fetchWithRetry(`${GITHUB_API_BASE}/repos/${owner}/${repo}/commits?since=${sinceDate}&per_page=10`),
648:     fetchWithRetry(`${GITHUB_API_BASE}/repos/${owner}/${repo}/releases?per_page=5`),
649:     fetchWithRetry(`${GITHUB_API_BASE}/search/issues?q=repo:${owner}/${repo}+is:pr+is:merged+merged:>${sinceDateOnly}&sort=updated&order=desc&per_page=10`),
650:   ]);
651: 
652:   let commits = [];
653:   if (commitsRes.status === 'fulfilled' && commitsRes.value?.ok) {
654:     const data = await commitsRes.value.json();
655:     if (Array.isArray(data)) {
656:       commits = data.map((c) => ({
657:         sha: c.sha ? c.sha.slice(0, 7) : 'commit',
658:         message: c.commit?.message ? c.commit.message.split('\n')[0] : 'Commit',
659:         author: c.commit?.author?.name || c.author?.login || 'contributor',
660:         date: c.commit?.author?.date || c.commit?.committer?.date,
661:         htmlUrl: c.html_url,
662:       }));
663:     }
664:   }
665: 
666:   let releases = [];
667:   if (releasesRes.status === 'fulfilled' && releasesRes.value?.ok) {
668:     const data = await releasesRes.value.json();
669:     if (Array.isArray(data)) {
670:       releases = data
671:         .filter((r) => r.published_at && new Date(r.published_at) >= new Date(sinceDate))
672:         .map((r) => ({
673:           id: r.id,
674:           name: r.name || r.tag_name,
675:           tagName: r.tag_name,
676:           publishedAt: r.published_at,
677:           htmlUrl: r.html_url,
678:         }));
679:     }
680:   }
681: 
682:   let mergedPRs = [];
683:   if (prsRes.status === 'fulfilled' && prsRes.value?.ok) {
684:     const data = await prsRes.value.json();
685:     if (Array.isArray(data.items)) {
686:       mergedPRs = data.items.map((pr) => ({
687:         id: pr.id,
688:         number: pr.number,
689:         title: pr.title,
690:         htmlUrl: pr.html_url,
691:         mergedAt: pr.pull_request?.merged_at || pr.closed_at,
692:         author: pr.user?.login || 'contributor',
693:       }));
694:     }
695:   }
696: 
697:   return {
698:     days,
699:     sinceDate,
700:     commits,
701:     releases,
702:     mergedPRs,
703:     fetchedAt: new Date().toISOString(),
704:   };
705: };
