707: /**
708:  * Dependency Footprint Explorer
709:  * Reads declared dependencies from supported package manifests (package.json, Cargo.toml, requirements.txt, go.mod).
710:  */
711: export const getDependencyFootprint = async (owner, repo) => {
712:   const supportedManifests = [
713:     { path: 'package.json', ecosystem: 'npm', registryUrl: (name) => `https://www.npmjs.com/package/${name}` },
714:     { path: 'Cargo.toml', ecosystem: 'crates.io', registryUrl: (name) => `https://crates.io/crates/${name}` },
715:     { path: 'requirements.txt', ecosystem: 'PyPI', registryUrl: (name) => `https://pypi.org/project/${name}/` },
716:     { path: 'pyproject.toml', ecosystem: 'PyPI', registryUrl: (name) => `https://pypi.org/project/${name}/` },
717:     { path: 'go.mod', ecosystem: 'Go', registryUrl: (name) => `https://pkg.go.dev/${name}` },
718:   ];
719: 
720:   for (const manifest of supportedManifests) {
721:     try {
722:       const res = await fetchWithRetry(`${GITHUB_API_BASE}/repos/${owner}/${repo}/contents/${manifest.path}`);
723:       if (!res.ok) continue;
724: 
725:       const data = await res.json();
726:       if (!data.content) continue;
727: 
728:       let rawText = '';
729:       try {
730:         const cleanBase64 = data.content.replace(/\s/g, '');
731:         rawText = decodeURIComponent(
732:           Array.prototype.map.call(atob(cleanBase64), (c) => '%' + ('00' + c.charCodeAt(0).toString(16)).slice(-2)).join('')
733:         );
734:       } catch {
735:         rawText = atob(data.content.replace(/\s/g, ''));
736:       }
737: 
738:       const dependencies = [];
739:       const devDependencies = [];
740: 
741:       if (manifest.path === 'package.json') {
742:         const pkg = JSON.parse(rawText);
743:         Object.entries(pkg.dependencies || {}).forEach(([name, spec]) => {
744:           dependencies.push({ name, spec: String(spec), url: manifest.registryUrl(name), type: 'runtime' });
745:         });
746:         Object.entries(pkg.devDependencies || {}).forEach(([name, spec]) => {
747:           devDependencies.push({ name, spec: String(spec), url: manifest.registryUrl(name), type: 'dev' });
748:         });
749:       } else if (manifest.path === 'Cargo.toml') {
750:         let currentSection = '';
751:         rawText.split('\n').forEach((line) => {
752:           const trimmed = line.trim();
753:           if (trimmed.startsWith('[dependencies]')) {
754:             currentSection = 'dependencies';
755:           } else if (trimmed.startsWith('[dev-dependencies]')) {
756:             currentSection = 'dev-dependencies';
757:           } else if (trimmed.startsWith('[')) {
758:             currentSection = '';
759:           } else if (currentSection && trimmed && !trimmed.startsWith('#')) {
760:             const eqIndex = trimmed.indexOf('=');
761:             if (eqIndex > 0) {
762:               const name = trimmed.slice(0, eqIndex).trim();
763:               const spec = trimmed.slice(eqIndex + 1).trim().replace(/^["']|["']$/g, '');
764:               const item = { name, spec, url: manifest.registryUrl(name), type: currentSection === 'dependencies' ? 'runtime' : 'dev' };
765:               if (currentSection === 'dependencies') dependencies.push(item);
766:               else devDependencies.push(item);
767:             }
768:           }
769:         });
770:       } else if (manifest.path === 'requirements.txt') {
771:         rawText.split('\n').forEach((line) => {
772:           const trimmed = line.trim();
773:           if (!trimmed || trimmed.startsWith('#')) return;
774:           const match = trimmed.match(/^([a-zA-Z0-9_.-]+)(.*)$/);
775:           if (match) {
776:             const name = match[1];
777:             const spec = match[2]?.trim() || 'any';
778:             dependencies.push({ name, spec, url: manifest.registryUrl(name), type: 'runtime' });
779:           }
780:         });
781:       } else if (manifest.path === 'go.mod') {
782:         let inRequire = false;
783:         rawText.split('\n').forEach((line) => {
784:           const trimmed = line.trim();
785:           if (trimmed.startsWith('require (')) {
786:             inRequire = true;
787:           } else if (inRequire && trimmed.startsWith(')')) {
788:             inRequire = false;
789:           } else if (inRequire || trimmed.startsWith('require ')) {
790:             const cleanLine = trimmed.replace(/^require\s+/, '');
791:             const parts = cleanLine.split(/\s+/);
792:             if (parts.length >= 2) {
793:               dependencies.push({ name: parts[0], spec: parts[1], url: manifest.registryUrl(parts[0]), type: 'runtime' });
794:             }
795:           }
796:         });
797:       }
798: 
799:       return {
800:         manifestFound: true,
801:         manifestPath: manifest.path,
802:         ecosystem: manifest.ecosystem,
803:         fileUrl: data.html_url || `https://github.com/${owner}/${repo}/blob/HEAD/${manifest.path}`,
804:         dependencies,
805:         devDependencies,
806:         totalCount: dependencies.length + devDependencies.length,
807:         scanTime: new Date().toISOString(),
808:       };
809:     } catch {
810:       // Continue to next manifest
811:     }
812:   }
813: 
814:   return {
815:     manifestFound: false,
816:     manifestPath: null,
817:     ecosystem: null,
818:     dependencies: [],
819:     devDependencies: [],
820:     totalCount: 0,
821:     scanTime: new Date().toISOString(),
822:     error: 'No supported package manifest detected (package.json, Cargo.toml, requirements.txt, pyproject.toml, go.mod).',
823:   };
824: };
