839:       const [details, latestRelease] = await Promise.allSettled([
840:         getRepositoryDetails(owner, repo),
841:         getLatestRelease(owner, repo),
842:       ]);
843: 
844:       const repoData = details.status === 'fulfilled' ? details.value : null;
845:       const releaseData = latestRelease.status === 'fulfilled' ? latestRelease.value : null;
846: 
847:       if (!repoData) return { error: `Repository ${owner}/${repo} could not be loaded.` };
848: 
849:       return {
850:         id: repoData.id,
851:         fullName: repoData.full_name || `${owner}/${repo}`,
852:         name: repoData.name,
853:         owner: repoData.owner,
854:         htmlUrl: repoData.html_url,
855:         description: repoData.description,
856:         stars: repoData.stargazers_count,
857:         forks: repoData.forks_count,
858:         openIssues: repoData.open_issues_count,
859:         language: repoData.language,
860:         languages: repoData.languages || {},
861:         updatedAt: repoData.updated_at,
862:         pushedAt: repoData.pushed_at,
863:         license: repoData.license,
864:         archived: repoData.archived,
865:         latestRelease: releaseData,
866:         fetchedAt: new Date().toISOString(),
867:       };
868:     } catch (err) {
869:       return { fullName: `${owner}/${repo}`, error: err.message };
870:     }
871:   });
872: 
873:   const results = await Promise.all(promises);
874:   return results.filter(Boolean);
875: };
