/**
 * PAT Token Optimization Script
 * Applies a comprehensive set of token-usage optimizations across githubService.js,
 * gemsService.js, RepositoryDetail.jsx, and WhatChangedDigest.jsx
 */
import fs from 'fs';

function patch(filePath, description, oldStr, newStr) {
  let content = fs.readFileSync(filePath, 'utf8');
  const norm = s => s.replace(/\r\n/g, '\n');
  const normContent = norm(content);
  const normOld = norm(oldStr);
  if (!normContent.includes(normOld)) {
    console.error(`❌  [${description}] Target not found in ${filePath}`);
    process.exit(1);
  }
  const updated = normContent.replace(normOld, norm(newStr));
  fs.writeFileSync(filePath, updated, 'utf8');
  console.log(`✅  [${description}]`);
}

