2:  * Structured Logging Service for HTTP status codes, error details, and system monitoring.
3:  */
4: 
5: const formatLog = (level, message, meta = {}) => {
6:     const logEntry = {
7:         timestamp: new Date().toISOString(),
8:         level,
9:         message,
10:         ...meta
11:     };
12:     return JSON.stringify(logEntry);
13: };
14: 
15: const logger = {
16:     info: (message, meta) => {
17:         console.log(`[INFO] ${formatLog('info', message, meta)}`);
18:     },
19:     warn: (message, meta) => {
20:         console.warn(`[WARN] ${formatLog('warn', message, meta)}`);
21:     },
22:     error: (message, meta) => {
23:         console.error(`[ERROR] ${formatLog('error', message, meta)}`);
24:     },
25:     logRequestError: (err, req, statusCode) => {
26:         const clientIp =
27:             req.headers['x-forwarded-for']?.split(',')[0].trim() ||
28:             req.socket?.remoteAddress ||
29:             '127.0.0.1';
30: 
31:         const errorMeta = {
32:             statusCode: statusCode || err.statusCode || err.status || 500,
33:             method: req.method,
34:             path: req.originalUrl || req.url,
35:             ip: clientIp,
36:             userAgent: req.headers['user-agent'] || 'unknown',
37:             errorMessage: err.message || 'Unknown server error',
38:             errorCode: err.code || undefined,
39:             stack: process.env.NODE_ENV !== 'production' ? err.stack : undefined
40:         };
41: 
42:         if (errorMeta.statusCode >= 500) {
43:             console.error(`[HTTP ${errorMeta.statusCode}] 💥 SERVER_ERROR:`, formatLog('error', err.message, errorMeta));
44:         } else if (errorMeta.statusCode === 404) {
45:             console.warn(`[HTTP 404] 🔍 NOT_FOUND: ${req.method} ${req.originalUrl || req.url} from ${clientIp}`);
46:         } else {
47:             console.warn(`[HTTP ${errorMeta.statusCode}] ⚠️ CLIENT_ERROR:`, formatLog('warn', err.message, errorMeta));
48:         }
49:     }
50: };
51: 
52: module.exports = logger;

